import { Component, OnInit, ViewChild } from '@angular/core';
import { DatePickerComponent, DefaultsService, GovBrDatePickerModule, GovBrInputModule, GovBrSelectModule} from '@serpro/ngx-dsgovbr';
import { CommonModule } from '@angular/common';
import { TooltipModule } from 'ngx-bootstrap/tooltip';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { DadosAbertosService } from '../../../services/dados-abertos.service';
import { ConsultarAliquotasResultadoComponent } from '../consultar-aliquotas-resultado/consultar-aliquotas-resultado.component';

@Component({
  selector: 'consultar-aliquotas-uniao',
  templateUrl: './consultar-aliquotas-uniao.component.html',
  styleUrl: './consultar-aliquotas-uniao.component.scss',
  standalone: true,
  imports: [
    CommonModule,
    ReactiveFormsModule,
    TooltipModule,
    GovBrDatePickerModule,
    GovBrSelectModule,
    GovBrInputModule,
    ConsultarAliquotasResultadoComponent
  ],
  providers: [],
})
export class ConsultarAliquotasUniaoComponent implements OnInit {

  @ViewChild('datePicker') datePicker: DatePickerComponent | undefined;

  response: any = null;

  form!: FormGroup;

  constructor(
    private readonly dadosAbertosService: DadosAbertosService,
    private readonly formBuilder: FormBuilder,
    private readonly defaultsService: DefaultsService,
  ) { }

  ngOnInit(): void {
    this.defaultsService.labelRequired = '';
    this.form = this.formBuilder.group({
      dataControl: [new Date('01/01/2026'), [Validators.required]],
    });
  }

  resetarValores() {
    this.response = null;
  }

  dataControlChange(event: any) {
    this.resetarValores();
  }

  dataControlInputChange(event: any) {
    this.resetarValores();
    if (event.srcElement.value.length >= 10) {
      this.datePicker?.selectionInlineDone(new Date(event.srcElement.value));
    }
  }

  consultar() {
    this.resetarValores();
    let data = this.form.get('dataControl')?.value;
    if (this.form.valid) {
      this.dadosAbertosService.consultarAliquotasUniao(data).subscribe((data) => {
        this.response = data;
      });
    }
  }

}
