import { Component, OnInit, ViewChild } from '@angular/core';
import { DatePickerComponent, DefaultsService, GovBrDatePickerModule, GovBrSelectModule } from '@serpro/ngx-dsgovbr';
import { CommonModule } from '@angular/common';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { DadosAbertosService } from '../../../services/dados-abertos.service';
import { ConsultarAliquotasResultadoComponent } from '../consultar-aliquotas-resultado/consultar-aliquotas-resultado.component';

@Component({
  selector: 'consultar-aliquotas-estado',
  templateUrl: './consultar-aliquotas-estado.component.html',
  styleUrl: './consultar-aliquotas-estado.component.scss',
  standalone: true,
  imports: [
    CommonModule,
    ReactiveFormsModule,
    GovBrDatePickerModule,
    GovBrSelectModule,
    ConsultarAliquotasResultadoComponent
  ],
  providers: [],
})
export class ConsultarAliquotasEstadoComponent implements OnInit {

  @ViewChild('datePicker') datePicker: DatePickerComponent | undefined;

  response: any = null;

  estadoValues: any[] = [];

  form!: FormGroup;

  constructor(
    private readonly dadosAbertosService: DadosAbertosService,
    private readonly formBuilder: FormBuilder,
    private readonly defaultsService: DefaultsService,
  ) { }

  ngOnInit(): void {
    this.defaultsService.labelRequired = '';
    this.form = this.formBuilder.group({
      dataControl: [new Date('01/01/2026'), [Validators.required]],
      estadoControl: [{ value: null, disabled: false }, [Validators.required]],
    });
    this.dadosAbertosService.obterUfs().subscribe({
      next: (data: any[]) => {
        this.estadoValues = data;
        data.sort((a, b) => (a.nome > b.nome) ? 1 : ((b.nome > a.nome) ? -1 : 0))
      }
    })
  }

  resetarValores() {
    this.response = null;
  }

  dataControlChange(event: any) {
    this.resetarValores();
  }

  dataControlInputChange(event: any) {
    this.resetarValores();
    if (event.srcElement.value.length >= 10) {
      this.datePicker?.selectionInlineDone(new Date(event.srcElement.value));
    }
  }

  estadoControlChange(event: any) {
    this.resetarValores();
  }

  consultar() {
    this.resetarValores();
    let data = this.form.get('dataControl')?.value;
    let estado = this.form.get('estadoControl')?.value?.codigo;
    if (this.form.valid) {
      this.dadosAbertosService.consultarAliquotasEstado(data, estado).subscribe((data) => {
        this.response = data;
      });
    }
  }

}
